    int i = end;
    while (i < headerPart.length()) {
        if (headerPart.charAt(i) == '\r' && i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
            return i + 2;
        }
        i++;
    }
    return -1; // Return -1 if no end of line is found
}

