import java.io.IOException;
import java.io.OutputStream;

public class ProtobufSerializer {

    /**
     * Serializes the {@code message}, prefixed with its length, into an {@link OutputStream}.
     * @return the size of the message
     */
    public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
        int size = schema.getSerializedSize(message);
        int tagSize = CodedOutputStream.computeUInt32SizeNoTag(size);
        int totalSize = size + tagSize;

        if (buffer.offset + totalSize > buffer.buffer.length) {
            buffer = LinkedBuffer.allocate(totalSize);
        }

        CodedOutputStream codedOutput = CodedOutputStream.newInstance(buffer.buffer, buffer.offset, totalSize);
        codedOutput.writeUInt32NoTag(size);
        schema.writeTo(codedOutput, message);
        codedOutput.checkNoSpaceLeft();

        out.write(buffer.buffer, buffer.offset, totalSize);
        buffer.offset += totalSize;

        return totalSize;
    }
}

