import org.apache.log4j.spi.LoggingEvent;

public class EventBuffer {
    private List<LoggingEvent> eventBuffer;
    private int MAX_BUFFER_SIZE;

    public EventBuffer(int maxBufferSize) {
        this.eventBuffer = new ArrayList<>();
        this.MAX_BUFFER_SIZE = maxBufferSize;
    }

    /**
     * Place a {@link LoggingEvent} in the buffer. If the buffer is full then the event is <b>silently dropped</b>.
     * It is the caller's responsibility to make sure that the buffer has free space.
     */
    public void put(LoggingEvent o) {
        if (this.eventBuffer.size() < MAX_BUFFER_SIZE) {
            this.eventBuffer.add(o);
        }
    }

    // Additional methods for completeness
    public String getDebugData() {
        return eventBuffer.toString();
    }

    public void clearEventLog() {
        this.eventBuffer.clear();
    }

    public String getData() {
        StringBuilder data = new StringBuilder();
        for (LoggingEvent event : eventBuffer) {
            data.append(event.toString()).append("\n");
        }
        return data.toString();
    }
}

