static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the number of days since the start of the month
    int daysInMonth = getDaysInMonth(year, month);
    int dayOffset = (day - 1) % dayStep;

    // Adjust the day to the nearest dayStep boundary
    int adjustedDay = dayOffset + 1;

    // Handle the case where the adjusted day exceeds the number of days in the month
    if (adjustedDay > daysInMonth) {
        adjustedDay = daysInMonth;
    }

    return year * 10000 + month * 100 + adjustedDay;
}

private static int getDaysInMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return isLeapYear(year) ? 29 : 28;
        default:
            throw new IllegalArgumentException("Invalid month: " + month);
    }
}

private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (ch <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

