public class SessionManager {
    private static final SecureRandom secureRandomInstance = new SecureRandom();
    private static final MessageDigest messageDigest;

    static {
        try {
            messageDigest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not found", e);
        }
    }

    /**
     * Generates a session ID.
     * @return A unique session ID.
     */
    public static String sessionId() {
        String randomString = new Integer(secureRandomInstance.nextInt()).toString();
        byte[] hashBytes = messageDigest.digest(randomString.getBytes());
        return hexEncode(hashBytes);
    }

    private static String hexEncode(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}

