     * Split a box along the x axis into two equal boxes.
     * @param box the box to split
     * @return a pair with the two resulting boxes
     */
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        double x = box.getX();
        double y = box.getY();
        double width = box.getWidth();
        double height = box.getHeight();

        double halfWidth = width / 2;

        Box2D box1 = new Box2D(x, y, halfWidth, height);
        Box2D box2 = new Box2D(x + halfWidth, y, halfWidth, height);

        return Pair.of(box1, box2);
