protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    List<E> path = new ArrayList<>(tour);
    List<V> vertexPath = new ArrayList<>();

    V currentVertex = graph.getEdgeSource(path.get(0));
    vertexPath.add(currentVertex);

    for (E edge : path) {
        V nextVertex = graph.getEdgeTarget(edge);
        vertexPath.add(nextVertex);
        currentVertex = nextVertex;
    }

    return new GraphPath<V, E>() {
        @Override
        public Graph<V, E> getGraph() {
            return graph;
        }

        @Override
        public V getStartVertex() {
            return vertexPath.get(0);
        }

        @Override
        public V getEndVertex() {
            return vertexPath.get(vertexPath.size() - 1);
        }

        @Override
        public List<E> getEdgeList() {
            return path;
        }

        @Override
        public List<V> getVertexList() {
            return vertexPath;
        }

        @Override
        public double getWeight() {
            double weight = 0;
            for (E edge : path) {
                weight += graph.getEdgeWeight(edge);
            }
            return weight;
        }
    };
}

