int addConstantNameAndType(final String name, final String descriptor) {
    int nameIndex = findUtf8(name);
    if (nameIndex == NOT_FOUND) {
        nameIndex = addUtf8(name);
    }

    int descriptorIndex = findUtf8(descriptor);
    if (descriptorIndex == NOT_FOUND) {
        descriptorIndex = addUtf8(descriptor);
    }

    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int[] nameAndType = (int[]) byteCode[i];
            if (nameAndType[0] == nameIndex && nameAndType[1] == descriptorIndex) {
                return i;
            }
        }
    }

    if (maxPoolSize >= byteCode.length) {
        throw new RuntimeException("Constant pool overflow");
    }

    int index = maxPoolSize++;
    byteCode[index] = new int[]{nameIndex, descriptorIndex};
    types[index] = NAME_TYPE;
    offsets[index] = 0;

    return index;
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                if (nextChar == '.' || nextChar == '\\' || nextChar == '*') {
                    result.append(nextChar);
                    i++; // Skip the next character as it's escaped
                } else {
                    result.append(c); // Keep the backslash if not followed by ., \, or *
                }
            } else {
                result.append(c); // Keep the backslash if it's the last character
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

