public class FileUtils {
    /**
     * Strip the filename extension from the given path, e.g. "mypath/myfile.txt" -> "mypath/myfile".
     * @param path the file path (may be <code>null</code>)
     * @return the path with stripped filename extension, or <code>null</code> if none
     */
    public static String stripFilenameExtension(String path) {
        if (path == null) {
            return null;
        }
        int loc0 = indexOfExtension(path);
        if (loc0 == -1) {
            return path;
        } else {
            return path.substring(0, loc0);
        }
    }

    private static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }
        int extensionPos = filename.lastIndexOf('.');
        int lastSeparatorPos = filename.lastIndexOf('/');
        int lastBackSeparatorPos = filename.lastIndexOf('\\');
        int separatorPos = Math.max(lastSeparatorPos, lastBackSeparatorPos);

        if (separatorPos > extensionPos) {
            return -1;
        }
        return extensionPos;
    }
}

