class DoublyLinkedList<E> {
    private AtomicReference<ListNode<E>> head;
    private AtomicReference<ListNode<E>> tail;

    public DoublyLinkedList() {
        head = new AtomicReference<>(null);
        tail = new AtomicReference<>(null);
    }

    public void addListNode(ListNode<E> node) {
        node.next = null;
        node.prev = tail.get();
        if (tail.get() != null) {
            tail.get().next = node;
        } else {
            head.set(node);
        }
        tail.set(node);
    }

    public boolean removeListNode(ListNode<E> node) {
        ListNode<E> prev = node.prev;
        ListNode<E> next = node.next;

        if (prev != null) {
            prev.next = next;
        } else {
            head.compareAndSet(node, next);
        }

        if (next != null) {
            next.prev = prev;
        } else {
            tail.compareAndSet(node, prev);
        }

        node.next = null;
        node.prev = null;
        return true;
    }

    public ListNode<E> getHead() {
        return head.get();
    }
}

public class ListMover<E> {
    private DoublyLinkedList<E> targetList;

    public ListMover(DoublyLinkedList<E> targetList) {
        this.targetList = targetList;
    }

    private void moveAllListNodes(DoublyLinkedList<E> list) {
        ListNode<E> current = list.getHead();
        while (current != null) {
            ListNode<E> next = current.next;
            list.removeListNode(current);
            targetList.addListNode(current);
            current = next;
        }
    }
}

